mapper.sql:
select a.*, ww.warehouse_name, wco.owner_code, wco.owner_name, wp.product_code, wp.product_name,
       wsl.location_type, wsz.zone_type
from wms_inventory a
inner join wms_products wp on a.product_id = wp.id
inner join wms_cargo_owners wco on wp.owner_id = wco.id
inner join wms_warehouses ww on a.warehouse_id = ww.id
inner join wms_storage_locations wsl on a.location_code = wsl.location_code and a.warehouse_id = wsl.warehouse_id
inner join wms_storage_zones wsz on wsl.zone_id = wsz.id



        and wco.owner_code = #{inv.ownerCode}



        and wco.owner_name like concat('%', #{inv.ownerName}, '%')



        and wp.product_code = #{inv.productCode}



        and wp.product_name like concat('%', #{inv.productName}, '%')



        and a.location_code = #{inv.locationCode}



        and wsz.zone_type = #{inv.zoneType}



        and a.warehouse_id = #{inv.warehouseId}



        and a.product_id = #{inv.productId}



        and a.id in

            #{id}



order by a.create_time desc, a.id desc

mapper.select:
select a.*
from wms_inventory a
where a.product_id = #{productId}
  and a.warehouse_id = #{warehouseId}
  and a.is_sellable = '1'
  and ifnull(a.available_quantity, 0) > 0

    and a.batch_number = #{batchNumber}

order by case when a.expiry_date is null then 1 else 0 end, a.expiry_date asc, a.stock_in_time asc, a.id asc

mapper.update:
update wms_inventory
set available_quantity = available_quantity - #{quantity},
    allocated_quantity = ifnull(allocated_quantity, 0) + #{quantity},
    update_time = #{now}
where id = #{id}
  and ifnull(available_quantity, 0) >= #{quantity}

update wms_inventory
set stock_quantity = stock_quantity + #{quantity},
    available_quantity = ifnull(available_quantity, 0) + #{availableQuantity},
    update_time = #{now}
where id = #{id}

update wms_inventory
set stock_quantity = stock_quantity - #{quantity},
    available_quantity = ifnull(available_quantity, 0) - #{quantity},
    update_time = #{now}
where id = #{id}
  and stock_quantity >= #{quantity}
  and ifnull(available_quantity, 0) >= #{quantity}
